import numpy as np
lines = open('opt2.xyz').read().splitlines()
n = int(lines[0])
atoms=[]
for ln in lines[2:2+n]:
    p=ln.split()
    atoms.append([p[0], float(p[1]),float(p[2]),float(p[3])])
def dist(a,b):
    return np.linalg.norm(np.array(a[1:])-np.array(b[1:]))
# bond cutoffs
cut = {('Na','O'):2.9,('W','O'):2.3,('Mo','O'):2.3,('Mo','N'):2.1,('N','O'):1.5,('C','O'):1.6,('C','H'):1.2,('O','H'):1.15,('W','W'):3.0,('Mo','W'):3.0,('O','O'):1.7,('Na','W'):3.4,('Na','Mo'):3.4}
def getcut(e1,e2):
    for k,v in cut.items():
        if (e1,e2)==k or (e2,e1)==k: return v
    return 0
bonds=[]
for i in range(n):
    for j in range(i+1,n):
        c=getcut(atoms[i][0],atoms[j][0])
        if c>0 and dist(atoms[i],atoms[j])<c:
            bonds.append((i,j,round(dist(atoms[i],atoms[j]),2)))
for b in bonds:
    print(b[0],atoms[b[0]][0],'-',b[1],atoms[b[1]][0], b[2])
print('---- coordination ----')
from collections import defaultdict
coord=defaultdict(list)
for b in bonds:
    coord[b[0]].append(b[1]); coord[b[1]].append(b[0])
for i in range(n):
    print(i, atoms[i][0], 'bonds to:', [(j,atoms[j][0]) for j in coord[i]])
"

